float SampleFuzz ( vec2 uv, float rootToTip )
{
    uv *= iChannelResolution[0].xy;
    uv -= smoothstep(0.,1.,fract(uv))-fract(uv);
    uv /= iChannelResolution[0].xy;

    float threshold = mix(.5,.8,pow(rootToTip,1.5)); // shape along the length
    float softness = .3;
    vec4 tap = smoothstep(threshold,threshold+softness,texture(iChannel0,uv));
    return max(tap.a,tap.g);//,tap.b),tap.r);
}

void mainImage( out vec4 fragColour, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-iResolution.xy*.5)/iResolution.y;

    uv.y*=3.;
    uv = uv+uv.yx*vec2(1,-1);

    vec3 col = vec3(0);
    for ( float i = 0.0; i <= 1.0; i += .1 )
    {
        vec3 pattern = smoothstep(.47,.53,texture(iChannel0,uv*.001).rgb);
        col = mix( col, i*pattern, SampleFuzz( uv*.03, i ) );
        uv -= .012;
    }

    col = pow(col,vec3(1./2.2));
    fragColour = vec4(col,1);
}
